/**
 * @brief De-initialize LCD registers
 * @param LCDx LCD Instance
 * @return ErrorStatus value:
 *         SUCCESS: LCD registers are de-initialized
 *         ERROR:   Wrong LCD Port
 */
ErrorStatus LL_LCD_DeInit(LCD_TypeDef *LCDx)
{
    ErrorStatus status = SUCCESS;

    /* Check the parameters */
    assert_param(IS_LCD_ALL_INSTANCE(LCDx));

    if (LCDx == LCD_CORE0) {
        /* Force and Release reset on clock of LCDx Port */
        LL_SYSTEM_CORE0_MOD0_ForceReset(LL_SYSTEM_CORE0_MOD0_PERIPH_LCD);
        LL_SYSTEM_CORE0_MOD0_ReleaseReset(LL_SYSTEM_CORE0_MOD0_PERIPH_LCD);
    }
    else if(LCDx == LCD_CORE1)
    {
        /* Force and Release reset on clock of LCDx Port */
        LL_SYSTEM_CORE1_MOD0_ForceReset(LL_SYSTEM_CORE1_MOD0_PERIPH_LCD);
        LL_SYSTEM_CORE1_MOD0_ReleaseReset(LL_SYSTEM_CORE1_MOD0_PERIPH_LCD);
    }
    else {
        status = ERROR;
    }

    return status;
}

/**
 * @brief Initialize LCD registers according to the specified parameters in LCD_InitStruct.
 * @note  If select Pumb on, LCD voltage generated by internal PUMP. If select Pumb off, LCD voltage generated by resistance.
 *        Pumb on: the BiasLevel should be configured and parameters of ResCtrl_Init are invalid.
 *        Punm off: the parameters of ResCtrl_Init should be configured and BiasLevel is invalid.
 * @param LCDx LCD Instance
 * @param LCD_InitStruct pointer to LL_LCD_InitTypeDef structure
 * @return ErrorStatus:
 *         SUCCESS: LCD registers are de-initialized
 *         ERROR:   Not applicable
 */
ErrorStatus LL_LCD_Init(LCD_TypeDef *LCDx, LL_LCD_InitTypeDef *LCD_InitStruct)
{
    ErrorStatus status = SUCCESS;

    /* Check the parameters */
    assert_param(IS_LCD_ALL_INSTANCE(LCDx));
    assert_param(IS_LL_LCD_BIAS(LCD_InitStruct->Bias));
    assert_param(IS_LL_LCD_DUTY(LCD_InitStruct->Duty));
    assert_param(IS_LL_LCD_DRIVE_TYPE(LCD_InitStruct->DriveType));
    assert_param(IS_LL_LCD_PUMP(LCD_InitStruct->Pump));

    /* Note: Hardware constraint (refer to description of this function)  */
    /*       LCD instance must be disabled before configuring.     */
    if(LL_LCD_IsEnabled(LCDx) == 0UL)
    {
        /* Pump on-off configuration     */
        LL_LCD_SetPumpOnOff(LCDx, LCD_InitStruct->Pump);
        /* Duty configuration       */
        LL_LCD_SetDuty(LCDx, LCD_InitStruct->Duty);
        /* Drive type configuration */
        LL_LCD_SetDriveType(LCDx, LCD_InitStruct->DriveType);
        /* Bias configuration       */
        LL_LCD_SetBias(LCDx, LCD_InitStruct->Bias);
        /* Clock prescale configuration       */
        LL_LCD_SetClockDivision(LCDx, LCD_InitStruct->Division);
        /* Enable LCD Peripheral */
        LL_LCD_Enable(LCDx);
    }
    else
    {
        /* Initialization error: LCD instance is not disabled.  */
        return ERROR;
    }

    return status;
}

/**
 * @brief Set each @ref LL_LCD_InitTypeDef field to default value.
 * @param LCD_InitStruct pointer to LL_LCD_InitTypeDef structure
 * @retval None
 */
void LL_LCD_StructInit(LL_LCD_InitTypeDef *LCD_InitStruct)
{
    /* Reset LCD init structure parameters values */
    LCD_InitStruct->Pump      = LL_LCD_PUMP_ON;
    LCD_InitStruct->Bias      = LL_LCD_BIAS_1_3;
    LCD_InitStruct->Duty      = LL_LCD_DUTY_STATIC;
    LCD_InitStruct->DriveType = LL_LCD_DRIVE_A;
    LCD_InitStruct->Division  = 0U;
}
